import { test, expect, devices } from '@playwright/test';

test.describe('Mobile Landscape Orientation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should display correctly in landscape orientation on mobile', async ({ page }) => {
    // Set viewport to landscape orientation (width > height)
    await page.setViewportSize({ width: 812, height: 375 });

    // Wait for any layout adjustments
    await page.waitForLoadState('networkidle');

    // Verify the page is visible and not broken
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();

    // Check that content is not horizontally scrollable (no overflow)
    const bodyWidth = await page.evaluate(() => document.body.scrollWidth);
    const viewportWidth = await page.evaluate(() => window.innerWidth);
    expect(bodyWidth).toBeLessThanOrEqual(viewportWidth);
  });

  test('should maintain readable text size in landscape orientation', async ({ page }) => {
    await page.setViewportSize({ width: 812, height: 375 });
    await page.waitForLoadState('networkidle');

    // Get all text elements and verify they have reasonable font sizes
    const textElements = page.locator('body *');
    const count = await textElements.count();

    for (let i = 0; i < Math.min(count, 10); i++) {
      const element = textElements.nth(i);
      const fontSize = await element.evaluate((el) => {
        return window.getComputedStyle(el).fontSize;
      });

      // Font size should be at least 12px for readability
      const fontSizeValue = parseInt(fontSize);
      if (fontSizeValue > 0) {
        expect(fontSizeValue).toBeGreaterThanOrEqual(12);
      }
    }
  });

  test('should have properly sized interactive elements in landscape', async ({ page }) => {
    await page.setViewportSize({ width: 812, height: 375 });
    await page.waitForLoadState('networkidle');

    // Check buttons are visible and have adequate touch target size
    const buttons = page.getByRole('button');
    const buttonCount = await buttons.count();

    if (buttonCount > 0) {
      const firstButton = buttons.first();
      const boundingBox = await firstButton.boundingBox();

      // Touch targets should be at least 44x44 pixels
      expect(boundingBox?.width).toBeGreaterThanOrEqual(44);
      expect(boundingBox?.height).toBeGreaterThanOrEqual(44);
    }
  });

  test('should not have layout shift when rotating to landscape', async ({ page }) => {
    // Start in portrait
    await page.setViewportSize({ width: 375, height: 667 });
    await page.waitForLoadState('networkidle');

    const portraitContent = page.getByRole('main');
    await expect(portraitContent).toBeVisible();

    // Rotate to landscape
    await page.setViewportSize({ width: 812, height: 375 });
    await page.waitForLoadState('networkidle');

    // Content should still be visible without major layout issues
    const landscapeContent = page.getByRole('main');
    await expect(landscapeContent).toBeVisible();

    // Verify no horizontal scrollbar appears
    const hasHorizontalScroll = await page.evaluate(() => {
      return document.documentElement.scrollWidth > window.innerWidth;
    });
    expect(hasHorizontalScroll).toBe(false);
  });

  test('should display navigation properly in landscape orientation', async ({ page }) => {
    await page.setViewportSize({ width: 812, height: 375 });
    await page.waitForLoadState('networkidle');

    // Check if navigation elements are accessible
    const nav = page.getByRole('navigation');
    if (await nav.count() > 0) {
      await expect(nav.first()).toBeVisible();

      // Verify navigation items are not hidden or overlapped
      const navItems = page.getByRole('link');
      const navItemCount = await navItems.count();

      if (navItemCount > 0) {
        for (let i = 0; i < navItemCount; i++) {
          const item = navItems.nth(i);
          const isVisible = await item.isVisible();
          if (isVisible) {
            const boundingBox = await item.boundingBox();
            expect(boundingBox?.width).toBeGreaterThan(0);
            expect(boundingBox?.height).toBeGreaterThan(0);
          }
        }
      }
    }
  });
});
